func TestRunUpdatesFile(t *testing.T) {
	t.Chdir(t.TempDir())
	require.NoError(t, os.WriteFile("version.txt", []byte("version=1.0.0\n"), 0o640))

	env := map[string]string{
		"SEMREL_VERSION":      "v1.1.0",
		"SEMREL_TAG_PREFIX":   "v",
		"SEMREL_PLUGIN_FILES": "version.txt",
		"SEMREL_PLUGIN_FROM":  `version=\d+\.\d+\.\d+`,
		"SEMREL_PLUGIN_TO":    "version=${nextRelease.version}",
	}
	var stdout bytes.Buffer
	var stderr bytes.Buffer

	require.Equal(t, 0, run(&stdout, &stderr, envMap(env)))
	require.Equal(t, "version.txt\n", stdout.String())
	require.Contains(t, stderr.String(), "updated version.txt (matches=1 replacements=1)")
	content, err := os.ReadFile("version.txt")
	require.NoError(t, err)
	require.Equal(t, "version=1.1.0\n", string(content))
	info, err := os.Stat("version.txt")
	require.NoError(t, err)
	require.Equal(t, os.FileMode(0o640), info.Mode().Perm())
}

func TestRunDryRunValidatesWithoutWriting(t *testing.T) {
	t.Chdir(t.TempDir())
	require.NoError(t, os.WriteFile("README.md", []byte("release-v1.0.0\n"), 0o644))

	env := map[string]string{
		"SEMREL_VERSION":              "v1.1.0",
		"SEMREL_TAG_PREFIX":           "v",
		"SEMREL_DRY_RUN":              "true",
		"SEMREL_PLUGIN_FILES":         "README.md",
		"SEMREL_PLUGIN_FROM":          `release-v\d+\.\d+\.\d+`,
		"SEMREL_PLUGIN_TO":            "release-v${SEMREL_VERSION}",
		"SEMREL_PLUGIN_COUNT_MATCHES": "true",
	}
	var stdout bytes.Buffer
	var stderr bytes.Buffer

	require.Equal(t, 0, run(&stdout, &stderr, envMap(env)))
	require.True(t, strings.HasPrefix(stderr.String(), "plugin_schema_version=1\n"))
	require.Contains(t, stderr.String(), "[dry-run] updater-replace: would update README.md")
	require.Contains(t, stdout.String(), "--- a/README.md\n+++ b/README.md\n")
	require.Contains(t, stdout.String(), "-release-v1.0.0\n+release-vv1.1.0\n")
	content, err := os.ReadFile("README.md")
	require.NoError(t, err)
	require.Equal(t, "release-v1.0.0\n", string(content))
}

