func TestRunStructuredRules(t *testing.T) {
	t.Chdir(t.TempDir())
	require.NoError(t, os.MkdirAll(filepath.Join("docs", "ignored"), 0o755))
	require.NoError(t, os.WriteFile(filepath.Join("docs", "one.md"), []byte("VERSION=1"), 0o644))
	require.NoError(t, os.WriteFile(filepath.Join("docs", "ignored", "two.md"), []byte("VERSION=1"), 0o644))

	env := map[string]string{
		"SEMREL_VERSION":    "v2.0.0",
		"SEMREL_TAG_PREFIX": "v",
		"SEMREL_PLUGIN_REPLACEMENTS": `
- files: ["docs/**/*.md"]
  ignore: ["docs/ignored/**"]
  from: "VERSION=\\d+"
  to: "VERSION=${nextRelease.version}"
  results:
    - file: docs/one.md
      hasChanged: true
      numMatches: 1
      numReplacements: 1
`,
	}
	var stdout bytes.Buffer
	var stderr bytes.Buffer

	require.Equal(t, 0, run(&stdout, &stderr, envMap(env)))
	require.Equal(t, "docs/one.md\n", stdout.String())
	requireFileContains(t, filepath.Join("docs", "one.md"), "VERSION=2.0.0")
	requireFileContains(t, filepath.Join("docs", "ignored", "two.md"), "VERSION=1")
}

func envMap(values map[string]string) func(string) string {
	return func(key string) string {
		return values[key]
	}
}

func requireFileContains(t *testing.T, path, expected string) {
	t.Helper()
	content, err := os.ReadFile(path)
	require.NoError(t, err)
	require.Contains(t, string(content), expected)
}
